(()=>{
 const {day,gap,summarize}=LuxWeeklyEvidence,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function read(k){try{return JSON.parse(localStorage.getItem(k)||'{}')}catch{return {}}}
 function render(){const biology=read('scholar-biology-cell-practice-v1'),assessment=read('lux-assessment-v1'),extra=[...(biology.practiceEvidence||[]),...(assessment.practiceEvidence||[])],state=read('lux-scholar-garden-v1').state||{},end=day(Date.now()-Number(document.getElementById('week').value)*86400000),subject=document.getElementById('subject').value,r=summarize([...(state.formalAttemptLog||[]),...extra],end,subject),start=day(Date.parse(end+'T12:00Z')-6*86400000);
  const link=t=>`/study/${encodeURIComponent(t.subject)}/practise/?mode=standard&year=${t.year}${t.topicId?'&topic='+encodeURIComponent(t.topicId):''}`;
  const list=(rows,empty)=>rows.length?'<ul>'+rows.map(t=>`<li><a href="${link(t)}">${esc(t.title)}</a> · ${esc(t.subject)} · Year ${esc(t.year)} · ${t.correct}/${t.attempted} independent correct${t.retained?` · ${t.retained} delayed checks passed`:''}</li>`).join('')+'</ul>':`<p>${empty}</p>`;
  const additional=globalThis.LuxPracticeBridge.additionalSummary(extra,end,subject);
  const extrasHTML=additional.map(x=>{const title=x.source==='biology-cell'?'Biology cell practice':'Assessment weak-area follow-up',href=x.source==='biology-cell'?'/study/biology/practise/?mode=cellstructure':'/assessment/?tab=history',topics=(rows,empty)=>rows.length?'<ul>'+rows.map(t=>`<li>${esc(t.title)} · ${esc(t.subject)} · <a href="${href}">Open practice</a></li>`).join('')+'</ul>':`<p>${empty}</p>`;return `<section><h2>${title}</h2><p><b>${x.attempted}</b> answers checked · <b>${x.correct}</b> full-mark answers · <b>${Math.round(x.earned*100)/100} / ${x.marks}</b> available marks earned</p><h3>Improving</h3>${topics(x.improved,'No recorded wrong-to-correct change yet.')}<h3>Needs follow-up</h3>${topics(x.followup,'No gap identified in the recorded checks for this period.')}<p class="muted">Recorded separately from formal mastery. Counts start with new checks after this connection was added; earlier undated follow-up cannot be reconstructed.</p></section>`}).join('');
  const results=(read('lux-assessment-v1').results||[]).filter(x=>{let date=String(x.date||x.at||x.completedAt||'').slice(0,10);if(/^\d{2}\/\d{2}\/\d{4}$/.test(date))date=date.split('/').reverse().join('-');return /^\d{4}-\d{2}-\d{2}$/.test(date)&&gap(end,date)>=0&&gap(end,date)<7&&(subject==='all'||String(x.paperId||x.id||'').includes(subject))});
  document.getElementById('summary').innerHTML=`<section><h2>${esc(start)} – ${esc(end)}</h2><div class="weekly-counts"><div><strong>${r.attempted}</strong>Answers attempted</div><div><strong>${r.correct} / ${r.formal}</strong>Formal independent correct</div><div><strong>${r.retained}</strong>Remembered after 2+ days</div></div><p>${r.activities} vocabulary / other independent non-formal answers · ${r.repairs} repair / follow-up answers, counted separately.</p><p class="muted">Delayed checks require the same question to be answered independently and correctly at least two days after the previous independent correct answer. Same-day repeats and guided repairs do not qualify.</p><p class="muted">${state.evidenceStartedAt?`Dated answer recording began ${esc(day(state.evidenceStartedAt))}.`:'Detailed formal recording starts with your next formal practice answer.'} Older progress cannot be reconstructed into weekly totals. Counts include recorded practice and weak-area checks on this device. Full-paper scores and reading time are separate.</p></section><section><h2>Improving this week</h2>${list(r.improved,'No recorded wrong-to-correct change in this period yet.')}<p class="muted">An improved answer needs a later independent correct attempt after a mistake in this week. Keep practising until delayed checks confirm retention.</p></section><section><h2>Needs follow-up</h2>${list(r.followup,'No weak topic identified from this period’s recorded answers. Unchecked topics are still unverified.')}<p>Use topic practice, then return after two days for a fresh independent check.</p></section><section><h2>Subject and topic evidence</h2>${r.topics.length?`<div class="table-scroll"><table><thead><tr><th>Topic</th><th>Independent correct</th><th>Delayed checks</th></tr></thead><tbody>${r.topics.map(t=>`<tr><td>${esc(t.title)}<br><small>${esc(t.subject)} · Year ${esc(t.year)}</small></td><td>${t.correct} / ${t.attempted}</td><td>${t.retained}</td></tr>`).join('')}</tbody></table></div>`:'<p>No dated independent answers recorded for this selection.</p>'}</section>${extrasHTML}<section><h2>Practice papers</h2><p>${results.length?`${results.length} full paper result(s) recorded in this period.`:'No dated full-paper result recorded for this selection.'} <a href="/assessment/">Open paper results and mark-point feedback</a>.</p></section>`;
 }
 document.getElementById('week').onchange=render;document.getElementById('subject').onchange=render;document.getElementById('print').onclick=()=>window.print();window.addEventListener('storage',render);render();
})();
